// Regras do spot de áudio (as mesmas na criação, na revisão, no refazer e na página de ouvir).
// corta no fim de uma frase (ou de uma palavra, com "…"): nunca no meio da palavra
const spT = (v, max) => {
  const s = String(v ?? '').replace(/\s+/g, ' ').trim();
  if (s.length <= max) return s;
  const c = s.slice(0, max), fim = Math.max(c.lastIndexOf('. '), c.lastIndexOf('! '), c.lastIndexOf('? '));
  if (fim >= max * 0.55) return c.slice(0, fim + 1);
  const esp = c.lastIndexOf(' ');
  return (esp >= max * 0.55 ? c.slice(0, esp) : c.slice(0, max - 1)).replace(/[\s,;:.–—-]+$/, '') + '…';
};
const spL = (v, max) => spT(v, max).replace(/[<>{}]/g, '');
const spEsc = v => String(v ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const spNum = v => {
  let s = String(v ?? '').replace(/[^\d,.]/g, '');
  if (!s) return null;
  if (/,\d{1,2}$/.test(s)) s = s.replace(/\./g, '').replace(',', '.'); else if (/^\d{1,3}(\.\d{3})+$/.test(s)) s = s.replace(/\./g, ''); else s = s.replace(/,/g, '');
  const n = Number(s); return isFinite(n) && n >= 0 ? Math.round(n * 100) / 100 : null;
};
const spHex = h => { h = String(h || '').replace('#', ''); return [0, 2, 4].map(i => parseInt(h.slice(i, i + 2), 16) || 0); };
const spLum = h => spHex(h).map(v => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); }).reduce((a, v, i) => a + v * [0.2126, 0.7152, 0.0722][i], 0);
const spContraste = (a, b) => { const x = spLum(a), y = spLum(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); };
const spMistura = (a, b, k) => { const x = spHex(a), y = spHex(b); return '#' + x.map((v, i) => Math.round(v + (y[i] - v) * k).toString(16).padStart(2, '0')).join('').toUpperCase(); };
function spTokens(cor) {
  const c = /^#[0-9a-fA-F]{6}$/.test(cor || '') ? String(cor).toUpperCase() : '#E4572E';
  let forte = c;
  for (let i = 0; i < 16 && spContraste(forte, '#FFFFFF') < 4.5; i++) forte = spMistura(forte, '#000000', 0.12);
  return { cor: c, forte, tinta: spContraste('#FFFFFF', forte) >= 4.5 ? '#FFFFFF' : '#111111', suave: spMistura(c, '#FFFFFF', 0.9), linha: spMistura(c, '#FFFFFF', 0.72), escuro: spMistura(forte, '#000000', 0.55) };
}

// ── números por extenso (a voz lê do jeito que o locutor falaria) ──
const SP_U = ['zero', 'um', 'dois', 'três', 'quatro', 'cinco', 'seis', 'sete', 'oito', 'nove', 'dez', 'onze', 'doze', 'treze', 'catorze', 'quinze', 'dezesseis', 'dezessete', 'dezoito', 'dezenove'];
const SP_D = ['', '', 'vinte', 'trinta', 'quarenta', 'cinquenta', 'sessenta', 'setenta', 'oitenta', 'noventa'];
const SP_C = ['', 'cento', 'duzentos', 'trezentos', 'quatrocentos', 'quinhentos', 'seiscentos', 'setecentos', 'oitocentos', 'novecentos'];
const SP_MESES = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];
const SP_ORD = ['', 'primeiro', 'segundo', 'terceiro', 'quarto', 'quinto', 'sexto', 'sétimo', 'oitavo', 'nono', 'décimo'];
function spAte999(n) {
  if (n === 100) return 'cem';
  const c = Math.floor(n / 100), r = n % 100, p = [];
  if (c) p.push(SP_C[c]);
  if (r) p.push(r < 20 ? SP_U[r] : SP_D[Math.floor(r / 10)] + (r % 10 ? ' e ' + SP_U[r % 10] : ''));
  return p.join(' e ');
}
function spExtenso(n, fem) {
  n = Math.floor(Math.abs(Number(n) || 0));
  if (!n) return 'zero';
  if (n >= 1e9) return String(n);
  const g = [Math.floor(n / 1e6), Math.floor(n / 1000) % 1000, n % 1000];
  const nomes = [x => x === 1 ? 'um milhão' : spAte999(x) + ' milhões', x => x === 1 ? 'mil' : spAte999(x) + ' mil', spAte999];
  const partes = g.map((x, i) => x ? { x, t: nomes[i](x), i } : null).filter(Boolean);
  // "mil e quinhentos", "dois mil e vinte", mas "mil duzentos e trinta"
  let s = partes.map((p, k) => k === 0 ? p.t : ((p.x < 100 || p.x % 100 === 0) ? ' e ' : ' ') + p.t).join('');
  if (fem) s = s.replace(/\bum\b(?! milh)/g, 'uma').replace(/\bdois\b/g, 'duas').replace(/entos\b/g, 'entas');
  return s;
}
const spReais = v => {
  const r = Math.floor(v + 1e-9), c = Math.round((v - r) * 100);
  const a = r ? spExtenso(r) + (r === 1 ? ' real' : r % 1e6 === 0 ? ' de reais' : ' reais') : '';
  const b = c ? spExtenso(c) + (c === 1 ? ' centavo' : ' centavos') : '';
  return a && b ? a + ' e ' + b : a || b || 'zero reais';
};
// telefone dito em grupos: "nove um, nove oito oito oito oito, sete sete sete sete"
function spDigitos(d) {
  const g = d.startsWith('0800') && d.length >= 10 ? [4, 3, d.length - 7] : d.length === 11 ? [2, 5, 4] : d.length === 10 ? [2, 4, 4] : d.length === 9 ? [5, 4] : d.length === 8 ? [4, 4] : null;
  const partes = [];
  if (g) { let i = 0; for (const n of g) { partes.push(d.slice(i, i + n)); i += n; } } else for (let i = 0; i < d.length; i += 4) partes.push(d.slice(i, i + 4));
  return partes.map(p => p.split('').map(x => SP_U[Number(x)]).join(' ')).join(', ');
}
const SP_FONE = /\(?\b0?\d{2}\)?[\s.-]?9?\d{4}[\s.-]?\d{4}\b|\b9?\d{4}-\d{4}\b|\b0800[\s.-]?\d{3}[\s.-]?\d{4}\b/g;
const SP_REAL = /R\$\s?(\d{1,3}(?:\.\d{3})+|\d+)(?:,(\d{1,2}))?/g;
// texto escrito (com R$ 19,90, (91) 98888-7777, 8h, 25/10, 50%) ➜ texto falado
function spFalada(t) {
  let s = String(t || '');
  s = s.replace(SP_FONE, m => spDigitos(m.replace(/\D/g, '')));
  s = s.replace(SP_REAL, (m, r, c) => spReais(Number(r.replace(/\./g, '')) + (c ? Number(c.padEnd(2, '0')) / 100 : 0)));
  s = s.replace(/(\d+)(?:,(\d+))?\s?%/g, (m, a, b) => spExtenso(a) + (b ? ' vírgula ' + spExtenso(b) : '') + ' por cento');
  s = s.replace(/\b(\d{1,2})\/(\d{1,2})(?:\/(\d{2,4}))?\b/g, (m, d, me, a) => Number(me) >= 1 && Number(me) <= 12 && Number(d) >= 1 && Number(d) <= 31
    ? (Number(d) === 1 ? 'primeiro' : spExtenso(d)) + ' de ' + SP_MESES[Number(me) - 1] : m);
  s = s.replace(/\b(\d{1,2})(?:h|:)(\d{2})\b/gi, (m, h, mi) => spExtenso(h, true) + (Number(mi) ? ' e ' + spExtenso(mi) : (Number(h) === 1 ? ' hora' : ' horas')));
  s = s.replace(/\b(\d{1,2})\s?h(?:s|rs)?\b/gi, (m, h) => spExtenso(h, true) + (Number(h) === 1 ? ' hora' : ' horas'));
  s = s.replace(/\b(\d{1,2})\s?([ºª°])/g, (m, n, o) => { const x = SP_ORD[Number(n)] || spExtenso(n); return o === 'ª' ? x.replace(/o$/, 'a') : x; });
  // dias da semana abreviados ("seg a sáb", "sáb e dom")
  const DIAS = { seg: 'segunda', ter: 'terça', qua: 'quarta', qui: 'quinta', sex: 'sexta', sab: 'sábado', 'sáb': 'sábado', dom: 'domingo' };
  const dia = x => DIAS[x.toLowerCase()] || x;
  s = s.replace(/\b(seg|ter|qua|qui|sex|s[áa]b|dom)\.?(\s?(?:a|à|e|-)\s?)(seg|ter|qua|qui|sex|s[áa]b|dom)\b\.?/gi, (m, a, meio, b) => dia(a) + (meio.trim() === '-' ? ' a ' : meio) + dia(b));
  s = s.replace(/\b(seg|s[áa]b)\b\.?/gi, m => dia(m.replace('.', '')));   // "dom" sozinho fica (é palavra: "o dom de…")
  s = s.replace(/\b(\d+)\s?x\b/gi, (m, n) => spExtenso(n, true) + (Number(n) === 1 ? ' vez' : ' vezes'));
  s = s.replace(/\b(\d+)\s?kg\b/gi, (m, n) => spExtenso(n) + (Number(n) === 1 ? ' quilo' : ' quilos'));
  s = s.replace(/\b(\d+)\s?km\b/gi, (m, n) => spExtenso(n) + (Number(n) === 1 ? ' quilômetro' : ' quilômetros'));
  s = s.replace(/\b(\d{1,3}(?:\.\d{3})+)\b/g, m => spExtenso(m.replace(/\./g, '')));
  s = s.replace(/\b(\d+),(\d+)\b/g, (m, a, b) => spExtenso(a) + ' vírgula ' + spExtenso(b));
  s = s.replace(/\d+/g, m => m.length > 6 ? spDigitos(m) : spExtenso(m));
  s = s.replace(/\bn[º°]\s?/gi, 'número ').replace(/\bAv\.\s/g, 'Avenida ').replace(/\bR\.\s(?=[A-ZÁÉÍÓÚ])/g, 'Rua ').replace(/\bDr\.\s/g, 'Doutor ').replace(/\bSta\.\s/g, 'Santa ')
    .replace(/\s&\s/g, ' e ').replace(/@(\w)/g, 'arroba $1').replace(/R\$/g, 'reais');
  return s.replace(/\s+/g, ' ').trim();
}
const spContaPalavras = t => String(t || '').split(/\s+/).filter(Boolean).length;
// valores em R$ escritos num texto (em centavos)
const spValores = t => [...String(t || '').matchAll(SP_REAL)].map(m => Math.round((Number(m[1].replace(/\./g, '')) + (m[2] ? Number(m[2].padEnd(2, '0')) / 100 : 0)) * 100));
// frases de um texto ("Av. Brasil", "Dr. João", "seg. a sáb." não terminam frase)
const SP_ABREV = /(?:^|[\s(])(?:av|r|dr|dra|sr|sra|sta|sto|prof|profa|n|nº|jd|pq|al|trav|rod|est|lj|cj|apto|ap|km|tel|cel|obs|seg|ter|qua|qui|sex|s[áa]b|dom)\.$/i;
const spFrases = t => {
  const out = [];
  for (const p of String(t || '').split(/(?<=[.!?…])\s+/)) { if (out.length && SP_ABREV.test(out[out.length - 1])) out[out.length - 1] += ' ' + p; else out.push(p); }
  return out.map(x => x.trim()).filter(Boolean);
};
// tira as frases que batem com a regra (devolve o texto sem elas)
const spTiraFrases = (t, teste) => spFrases(t).filter(f => !teste(f)).join(' ').trim();

// tamanho de cada versão (palavras FALADAS): medido no 1º teste real, as vozes falam ~2,3 palavras por segundo (com as pausas entre falas);
// a oficina pode acelerar até 15% e guarda 1,2 s de trilha antes e 1,6 s depois ➜ (alvo − 2,8) × 1,15 × 2,3
const SP_VERSOES = [{ nome: '15s', alvo: 15, max: 32 }, { nome: '30s', alvo: 30, max: 70 }, { nome: '60s', alvo: 60, max: 145 }];
const spPalavras = falas => falas.reduce((s, f) => s + spContaPalavras(spFalada(f.texto)), 0);
// versões do redator (ou do revisor) no formato do spot: falas A/B/V (V = vinheta); sem diálogo, tudo vira A (e V)
function spVersoes(r, V) {
  const rv = r && Array.isArray(r.versoes) ? r.versoes.filter(x => x && typeof x === 'object') : [];
  return SP_VERSOES.map((base, i) => {
    const x = rv.find(y => String(y.nome || '').replace(/\D/g, '') === String(base.alvo)) || rv[i] || {};
    let falas = (Array.isArray(x.falas) ? x.falas : []).filter(f => f && typeof f === 'object').map(f => ({ quem: ['A', 'B', 'V'].includes(String(f.quem).toUpperCase()) ? String(f.quem).toUpperCase() : 'A',
      texto: spL(f.texto, 400).replace(/\p{Extended_Pictographic}/gu, '').replace(/\s+/g, ' ').trim() })).filter(f => f.texto).slice(0, 16);
    if (!V.op.dialogo) falas = falas.map(f => ({ ...f, quem: f.quem === 'V' ? 'V' : 'A' }));
    return { ...base, falas, palavras: spPalavras(falas) };
  });
}
// trava das falas: preço só o do anunciante, telefone só o dele, sem urgência falsa e no tamanho da versão
function spTrava(versoes, V, trava) {
  const d = V.dados, permitidos = new Set([...spValores(d.preco), ...spValores(d.oferta), ...(spNum(d.preco) !== null && !/R\$/.test(d.preco) ? [Math.round(spNum(d.preco) * 100)] : [])]);
  const fone = String(d.telefone || '').replace(/\D/g, '');
  const urgencia = /s[oó] hoje|somente hoje|[uú]ltim[ao]s (unidades|horas|dias|vagas)|acaba hoje|corr[ae] que acaba|por tempo limitado|enquanto durar|n[aã]o perca tempo/i;
  return versoes.map(v => {
    const falas = [];
    for (const f of v.falas) {
      let t = f.texto;
      const ruins = spValores(t).filter(c => !permitidos.has(c));
      if (ruins.length) { t = spTiraFrases(t, fr => spValores(fr).some(c => !permitidos.has(c))); trava.push(`${v.nome}: tirei a frase com preço que o anunciante não deu (R$ ${(ruins[0] / 100).toFixed(2).replace('.', ',')})`); }
      const fones = (t.match(SP_FONE) || []).map(m => m.replace(/\D/g, '')).filter(x => !fone || !(fone.endsWith(x) || x.endsWith(fone)));
      if (fones.length) {
        if (fone) t = t.replace(SP_FONE, m => fone.endsWith(m.replace(/\D/g, '')) || m.replace(/\D/g, '').endsWith(fone) ? m : d.telefone);
        else t = spTiraFrases(t, fr => (fr.match(SP_FONE) || []).length > 0);
        trava.push(`${v.nome}: telefone diferente do anunciante ${fone ? 'trocado pelo dele' : 'tirado'}`);
      }
      if (!d.validade && urgencia.test(t)) { t = spTiraFrases(t, fr => urgencia.test(fr)); trava.push(`${v.nome}: tirei a urgência que o anunciante não deu ("só hoje", "últimas unidades")`); }
      if (t) falas.push({ ...f, texto: t });
    }
    // no tamanho: tira a FRASE menos importante (nunca a vinheta) até caber; preço, nome, produto e o gancho ficam por último
    const tiradas = [];
    while (spPalavras(falas) > v.max) {
      const excesso = spPalavras(falas) - v.max, cands = [];
      falas.forEach((f, i) => {
        if (f.quem === 'V') return;
        spFrases(f.texto).forEach((fr, j) => cands.push({ i, j, fr, nota: spImportancia(fr, V, i === 0 && j === 0), tam: spContaPalavras(spFalada(fr)) }));
      });
      const menor = Math.min(...cands.map(c => c.nota)), mesmas = cands.filter(c => c.nota === menor);
      // entre as de menor peso: a menor que já resolve; se nenhuma resolve sozinha, a maior
      const bastam = mesmas.filter(c => c.tam >= excesso).sort((a, b) => a.tam - b.tam);
      const pior = bastam[0] || mesmas.sort((a, b) => b.tam - a.tam)[0];
      if (!pior || cands.length === 1) break;
      const resto = spFrases(falas[pior.i].texto).filter((x, j) => j !== pior.j).join(' ');
      if (resto) falas[pior.i] = { ...falas[pior.i], texto: resto }; else falas.splice(pior.i, 1);
      tiradas.push(pior.fr);
    }
    if (tiradas.length) trava.push(`${v.nome}: estava longo para ${v.alvo} s, tirei ${tiradas.length} frase(s) que pesavam menos (${tiradas.map(x => '"' + spT(x, 50) + '"').join(', ')})`);
    return { ...v, falas, palavras: spPalavras(falas) };
  });
}
const spSemAcento = t => String(t || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
// quanto a frase pesa no anúncio: preço > nome do anunciante e produto > endereço e telefone > o resto; a 1ª frase (gancho) ganha um pouco
function spImportancia(fr, V, gancho) {
  const d = V.dados, s = spSemAcento(fr);
  const nome = spSemAcento(d.anunciante.replace(/\(.*?\)/g, '')).split(/\s+/).filter(Boolean).slice(-2).join(' ');
  const produto = (spSemAcento(d.oferta).match(/[a-z]{4,}/) || [''])[0];
  const rua = (spSemAcento(String(d.endereco || '').split(',')[0]).match(/[a-z]{4,}/g) || []).filter(x => !['avenida', 'rua', 'praca', 'travessa', 'rodovia', 'estrada'].includes(x)).pop() || '';
  let n = 0;
  if (spValores(fr).length) n += 4;
  if (nome && s.includes(nome)) n += 3;
  if (produto && s.includes(produto)) n += 3;
  if (rua && s.includes(rua)) n += 2;
  if ((fr.match(SP_FONE) || []).length) n += 2;
  if (gancho) n += 3;
  return n;
}
// hashtag que tenta ser o nome do anunciante tem que ser o nome certo ("#AçougueBomBom" ➜ "#AcougueBoiBom")
function spHashtags(t, V, trava) {
  const nome = V.dados.anunciante.replace(/\(.*?\)/g, '').trim(), certa = '#' + spSemAcento(nome).split(/[^a-z0-9]+/).filter(Boolean).map(p => p[0].toUpperCase() + p.slice(1)).join('');
  const inicio = (spSemAcento(nome).match(/[a-z0-9]{4,}/) || [''])[0];
  if (!inicio || certa.length < 4) return t;
  const alvo = certa.slice(1).toLowerCase(), vistas = new Set();
  return String(t || '').replace(/#[\p{L}\d_]+/gu, h => {
    const x = spSemAcento(h.slice(1));
    // "#Paroquia" (começo do nome) é hashtag de verdade; "#AçougueBomBom" é o nome escrito errado
    if (x.startsWith(inicio) && x !== alvo && !alvo.startsWith(x)) { trava.push(`legenda: hashtag "${h}" trocada por "${certa}"`); h = certa; }
    const k = spSemAcento(h);
    if (vistas.has(k)) return '';
    vistas.add(k);
    return h;
  }).replace(/[ \t]{2,}/g, ' ').trim();
}
// título da tela sem o preço (o preço vai no destaque, logo embaixo)
function spSemPreco(t) {
  let x = String(t || '').replace(/\s*(?:(?<![\p{L}\d])(?:por|a|apenas|s[óo]|de)\s+)?R\$\s?\d[\d.]*(?:,\d{1,2})?(?:\s+(?:o|a)\s+(?:quilo|kg|unidade|litro|pacote|caixa))?/giu, '')
    .replace(/\s+([!?.,])/g, '$1').replace(/\s{2,}/g, ' ').replace(/^[\s,;:–-]+|[\s,;:–-]+$/g, '').replace(/^(?:a|o|as|os|por|de)\s+/i, '').trim();
  x = x.charAt(0).toUpperCase() + x.slice(1);
  return x.replace(/[!.]*$/, '').length >= 8 ? x : String(t || '');
}
// status que a página de criação e a de ouvir leem (sem a chave)
function spStatus(sp) {
  const ARQ = String(sp.link).split('/webhook/')[0] + '/videos/arquivo/', prontas = sp.versoes.filter(v => v.mp3).length;
  return { id: sp.id, etapa: prontas ? 'pronto' : 'erro', versao: sp.versao, link: sp.link, segundos: sp.segundos, fundo: sp.fundo ? ARQ + sp.fundo : '',
    erro: prontas ? '' : 'A oficina não conseguiu gravar o áudio: ' + (sp.versoes[0].erro || 'tente de novo'),
    versoes: sp.versoes.map(v => ({ nome: v.nome, alvo: v.alvo, palavras: v.palavras, duracao: v.duracao, mp3: v.mp3 ? ARQ + v.mp3 : '', mp4: v.mp4 ? ARQ + v.mp4 : '', erro: v.erro || '', aviso: v.aviso || '' })),
    revisao: [...(sp.problemas || []), ...(sp.trava || [])].slice(0, 10) };
}
// sem nenhuma fala que preste: um texto simples com os dados do anunciante
function spPadrao(v, V) {
  const d = V.dados, partes = [`${d.anunciante}!`, d.oferta.replace(/[.!]*$/, '.'), d.preco ? d.preco.replace(/[.!]*$/, '.') : '', v.alvo >= 30 && d.validade ? `Válido ${d.validade.replace(/[.!]*$/, '.')}` : '',
    v.alvo >= 30 && d.endereco ? `Fica em ${d.endereco.replace(/[.!]*$/, '.')}` : '', d.telefone ? `WhatsApp ${d.telefone}.` : ''].filter(Boolean);
  return [{ quem: 'A', texto: partes.join(' ') }, { quem: 'V', texto: d.anunciante + (d.slogan ? '. ' + d.slogan.replace(/[.!]*$/, '.') : '.') }];
}

// Confere o pedido do anunciante: quem anuncia, o quê, preço/validade/endereço/contato (só o que ele escrever), tom, vozes, trilha e a foto do vídeo.
const crypto = require('crypto');
const req = $('🔔 Pedido do spot (POST)').first().json;
let b = req.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};
const base = String(req.webhookUrl || '').split('/webhook/')[0];
const erros = [];
const anunciante = spL(b.anunciante, 60), oferta = spL(b.oferta, 400);
if (anunciante.length < 2) erros.push('Diga quem está anunciando.');
if (oferta.length < 8) erros.push('Conte o que vai ser anunciado (a promoção, o evento ou o serviço).');
const TIPOS = { loja: 'loja ou comércio', restaurante: 'restaurante, lanchonete ou padaria', evento: 'evento, festa ou igreja', servico: 'serviço', carro: 'carro de som (rua)', espera: 'espera telefônica', radio: 'rádio' };
