  const out = [];
  for (const p of String(t || '').split(/(?<=[.!?…])\s+/)) { if (out.length && SP_ABREV.test(out[out.length - 1])) out[out.length - 1] += ' ' + p; else out.push(p); }
  return out.map(x => x.trim()).filter(Boolean);
};
// tira as frases que batem com a regra (devolve o texto sem elas)
const spTiraFrases = (t, teste) => spFrases(t).filter(f => !teste(f)).join(' ').trim();

// tamanho de cada versão (palavras FALADAS): medido no 1º teste real, as vozes falam ~2,3 palavras por segundo (com as pausas entre falas);
// a oficina pode acelerar até 15% e guarda 1,2 s de trilha antes e 1,6 s depois ➜ (alvo − 2,8) × 1,15 × 2,3
const SP_VERSOES = [{ nome: '15s', alvo: 15, max: 32 }, { nome: '30s', alvo: 30, max: 70 }, { nome: '60s', alvo: 60, max: 145 }];
const spPalavras = falas => falas.reduce((s, f) => s + spContaPalavras(spFalada(f.texto)), 0);
// versões do redator (ou do revisor) no formato do spot: falas A/B/V (V = vinheta); sem diálogo, tudo vira A (e V)
function spVersoes(r, V) {
  const rv = r && Array.isArray(r.versoes) ? r.versoes.filter(x => x && typeof x === 'object') : [];
  return SP_VERSOES.map((base, i) => {
    const x = rv.find(y => String(y.nome || '').replace(/\D/g, '') === String(base.alvo)) || rv[i] || {};
    let falas = (Array.isArray(x.falas) ? x.falas : []).filter(f => f && typeof f === 'object').map(f => ({ quem: ['A', 'B', 'V'].includes(String(f.quem).toUpperCase()) ? String(f.quem).toUpperCase() : 'A',
      texto: spL(f.texto, 400).replace(/\p{Extended_Pictographic}/gu, '').replace(/\s+/g, ' ').trim() })).filter(f => f.texto).slice(0, 16);
    if (!V.op.dialogo) falas = falas.map(f => ({ ...f, quem: f.quem === 'V' ? 'V' : 'A' }));
    return { ...base, falas, palavras: spPalavras(falas) };
