// Refazer UMA versão com o texto que o anunciante mudou na página (só com a chave): a mesma trava da criação e o texto vira fala de novo.
// O arquivo novo tem outro nome (spot-15sv2.mp3): o antigo continua tocando até o novo ficar pronto.
const q = $('🧩 Lê o pedido de refazer').first().json;
let sp = null;
try { sp = JSON.parse($('📖 Lê o spot (refazer)').first().json.sp || 'null'); } catch (e) {}
const recusa = (codigo, erro) => [{ json: { valido: false, codigo, resposta: JSON.stringify({ ok: false, erro }) } }];
if (!sp) return recusa(404, 'Spot não encontrado.');
if (!q.chave || q.chave !== sp.chave) return recusa(403, 'Chave errada: abra a página pelo link com a chave.');
if (Number(Object.values($('🧮 Conta os refazeres').first().json)[0]) > 20) return recusa(429, 'Muitas gravações nesta hora. Tente daqui a pouco.');
const k = sp.versoes.findIndex(v => v.nome === q.versao);
if (k < 0) return recusa(400, 'Versão inválida.');
const base = sp.versoes[k], V = { op: sp.op, dados: sp.dados }, trava = [];
const idx = SP_VERSOES.findIndex(x => x.nome === base.nome);
const v = spTrava([spVersoes({ versoes: [{ nome: base.nome, falas: q.falas }] }, V)[idx]], V, trava)[0];
if (!v.falas.length) return recusa(400, trava.length ? 'O texto foi barrado: ' + trava.join('; ') : 'Escreva pelo menos uma fala.');
const n = (Number(base.refeita) || 1) + 1, arquivo = base.nome + 'v' + n, job = `sp-${sp.id}-${arquivo}`;
const falas = v.falas.map(f => ({ ...f, fala: spFalada(f.texto) }));
const corpo = { job, deck: sp.id, area: 'spots', voz_a: sp.op.voz_a, voz_b: sp.op.voz_b, trilha: sp.op.trilha, fundo: sp.fundo || '',
  versoes: [{ nome: arquivo, alvo: base.alvo, falas: falas.map(f => ({ quem: f.quem, texto: f.fala })) }] };
const palavras = spPalavras(falas);
return [{ json: { valido: true, id: sp.id, k, nome: base.nome, arquivo, n, job, falas, palavras, trava, corpo: JSON.stringify(corpo),
  resposta: JSON.stringify({ ok: true, versao: base.nome, palavras, max: base.max, trava, aviso: palavras > base.max ? 'Ficou maior que o ideal: a voz vai acelerar um pouco ou passar do tempo.' : '' }) } }];

// Regras do spot de áudio (as mesmas na criação, na revisão, no refazer e na página de ouvir).
// corta no fim de uma frase (ou de uma palavra, com "…"): nunca no meio da palavra
const spT = (v, max) => {
  const s = String(v ?? '').replace(/\s+/g, ' ').trim();
  if (s.length <= max) return s;
  const c = s.slice(0, max), fim = Math.max(c.lastIndexOf('. '), c.lastIndexOf('! '), c.lastIndexOf('? '));
  if (fim >= max * 0.55) return c.slice(0, fim + 1);
  const esp = c.lastIndexOf(' ');
  return (esp >= max * 0.55 ? c.slice(0, esp) : c.slice(0, max - 1)).replace(/[\s,;:.–—-]+$/, '') + '…';
};
const spL = (v, max) => spT(v, max).replace(/[<>{}]/g, '');
const spEsc = v => String(v ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const spNum = v => {
  let s = String(v ?? '').replace(/[^\d,.]/g, '');
  if (!s) return null;
  if (/,\d{1,2}$/.test(s)) s = s.replace(/\./g, '').replace(',', '.'); else if (/^\d{1,3}(\.\d{3})+$/.test(s)) s = s.replace(/\./g, ''); else s = s.replace(/,/g, '');
  const n = Number(s); return isFinite(n) && n >= 0 ? Math.round(n * 100) / 100 : null;
};
const spHex = h => { h = String(h || '').replace('#', ''); return [0, 2, 4].map(i => parseInt(h.slice(i, i + 2), 16) || 0); };
const spLum = h => spHex(h).map(v => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); }).reduce((a, v, i) => a + v * [0.2126, 0.7152, 0.0722][i], 0);
const spContraste = (a, b) => { const x = spLum(a), y = spLum(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); };
const spMistura = (a, b, k) => { const x = spHex(a), y = spHex(b); return '#' + x.map((v, i) => Math.round(v + (y[i] - v) * k).toString(16).padStart(2, '0')).join('').toUpperCase(); };
