  const nomes = [x => x === 1 ? 'um milhão' : spAte999(x) + ' milhões', x => x === 1 ? 'mil' : spAte999(x) + ' mil', spAte999];
  const partes = g.map((x, i) => x ? { x, t: nomes[i](x), i } : null).filter(Boolean);
  // "mil e quinhentos", "dois mil e vinte", mas "mil duzentos e trinta"
  let s = partes.map((p, k) => k === 0 ? p.t : ((p.x < 100 || p.x % 100 === 0) ? ' e ' : ' ') + p.t).join('');
  if (fem) s = s.replace(/\bum\b(?! milh)/g, 'uma').replace(/\bdois\b/g, 'duas').replace(/entos\b/g, 'entas');
