  s = s.replace(/\b(\d{1,2})\s?h(?:s|rs)?\b/gi, (m, h) => spExtenso(h, true) + (Number(h) === 1 ? ' hora' : ' horas'));
  s = s.replace(/\b(\d{1,2})\s?([ºª°])/g, (m, n, o) => { const x = SP_ORD[Number(n)] || spExtenso(n); return o === 'ª' ? x.replace(/o$/, 'a') : x; });
