// Lê o roteiro do redator (versões de 15, 30 e 60 s) e prepara o pedido do revisor com os dados do anunciante e o tamanho de cada versão.
const V = $('🧩 Confere o pedido').first().json;
let r = null;
try { r = parseJSON($('🤖 Redator de spots').first().json.output); } catch (e) {}
const versoes = spVersoes(r, V);
const tela = r && r.tela && typeof r.tela === 'object' ? r.tela : {};
const roteiro = { slogan: spL(r && r.slogan, 80), tela: { titulo: spL(tela.titulo, 70), destaque: spL(tela.destaque, 60) }, legenda: spL(r && r.legenda, 700), imagem: spT(r && r.imagem, 500),
  versoes: versoes.map(v => ({ nome: v.nome, falas: v.falas })) };
