const SP_VERSOES = [{ nome: '15s', alvo: 15, max: 32 }, { nome: '30s', alvo: 30, max: 70 }, { nome: '60s', alvo: 60, max: 145 }];
const spPalavras = falas => falas.reduce((s, f) => s + spContaPalavras(spFalada(f.texto)), 0);
// versões do redator (ou do revisor) no formato do spot: falas A/B/V (V = vinheta); sem diálogo, tudo vira A (e V)
function spVersoes(r, V) {
  const rv = r && Array.isArray(r.versoes) ? r.versoes.filter(x => x && typeof x === 'object') : [];
  return SP_VERSOES.map((base, i) => {
    const x = rv.find(y => String(y.nome || '').replace(/\D/g, '') === String(base.alvo)) || rv[i] || {};
    let falas = (Array.isArray(x.falas) ? x.falas : []).filter(f => f && typeof f === 'object').map(f => ({ quem: ['A', 'B', 'V'].includes(String(f.quem).toUpperCase()) ? String(f.quem).toUpperCase() : 'A',
      texto: spL(f.texto, 400).replace(/\p{Extended_Pictographic}/gu, '').replace(/\s+/g, ' ').trim() })).filter(f => f.texto).slice(0, 16);
    if (!V.op.dialogo) falas = falas.map(f => ({ ...f, quem: f.quem === 'V' ? 'V' : 'A' }));
    return { ...base, falas, palavras: spPalavras(falas) };
  });
}
// trava das falas: preço só o do anunciante, telefone só o dele, sem urgência falsa e no tamanho da versão
function spTrava(versoes, V, trava) {
  const d = V.dados, permitidos = new Set([...spValores(d.preco), ...spValores(d.oferta), ...(spNum(d.preco) !== null && !/R\$/.test(d.preco) ? [Math.round(spNum(d.preco) * 100)] : [])]);
  const fone = String(d.telefone || '').replace(/\D/g, '');
  const urgencia = /s[oó] hoje|somente hoje|[uú]ltim[ao]s (unidades|horas|dias|vagas)|acaba hoje|corr[ae] que acaba|por tempo limitado|enquanto durar|n[aã]o perca tempo/i;
  return versoes.map(v => {
    const falas = [];
    for (const f of v.falas) {
      let t = f.texto;
      const ruins = spValores(t).filter(c => !permitidos.has(c));
      if (ruins.length) { t = spTiraFrases(t, fr => spValores(fr).some(c => !permitidos.has(c))); trava.push(`${v.nome}: tirei a frase com preço que o anunciante não deu (R$ ${(ruins[0] / 100).toFixed(2).replace('.', ',')})`); }
      const fones = (t.match(SP_FONE) || []).map(m => m.replace(/\D/g, '')).filter(x => !fone || !(fone.endsWith(x) || x.endsWith(fone)));
      if (fones.length) {
        if (fone) t = t.replace(SP_FONE, m => fone.endsWith(m.replace(/\D/g, '')) || m.replace(/\D/g, '').endsWith(fone) ? m : d.telefone);
        else t = spTiraFrases(t, fr => (fr.match(SP_FONE) || []).length > 0);
        trava.push(`${v.nome}: telefone diferente do anunciante ${fone ? 'trocado pelo dele' : 'tirado'}`);
      }
      if (!d.validade && urgencia.test(t)) { t = spTiraFrases(t, fr => urgencia.test(fr)); trava.push(`${v.nome}: tirei a urgência que o anunciante não deu ("só hoje", "últimas unidades")`); }
      if (t) falas.push({ ...f, texto: t });
    }
    // no tamanho: tira a FRASE menos importante (nunca a vinheta) até caber; preço, nome, produto e o gancho ficam por último
    const tiradas = [];
    while (spPalavras(falas) > v.max) {
      const excesso = spPalavras(falas) - v.max, cands = [];
      falas.forEach((f, i) => {
        if (f.quem === 'V') return;
        spFrases(f.texto).forEach((fr, j) => cands.push({ i, j, fr, nota: spImportancia(fr, V, i === 0 && j === 0), tam: spContaPalavras(spFalada(fr)) }));
      });
      const menor = Math.min(...cands.map(c => c.nota)), mesmas = cands.filter(c => c.nota === menor);
      // entre as de menor peso: a menor que já resolve; se nenhuma resolve sozinha, a maior
      const bastam = mesmas.filter(c => c.tam >= excesso).sort((a, b) => a.tam - b.tam);
      const pior = bastam[0] || mesmas.sort((a, b) => b.tam - a.tam)[0];
      if (!pior || cands.length === 1) break;
      const resto = spFrases(falas[pior.i].texto).filter((x, j) => j !== pior.j).join(' ');
      if (resto) falas[pior.i] = { ...falas[pior.i], texto: resto }; else falas.splice(pior.i, 1);
      tiradas.push(pior.fr);
    }
    if (tiradas.length) trava.push(`${v.nome}: estava longo para ${v.alvo} s, tirei ${tiradas.length} frase(s) que pesavam menos (${tiradas.map(x => '"' + spT(x, 50) + '"').join(', ')})`);
    return { ...v, falas, palavras: spPalavras(falas) };
  });
}
const spSemAcento = t => String(t || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
// quanto a frase pesa no anúncio: preço > nome do anunciante e produto > endereço e telefone > o resto; a 1ª frase (gancho) ganha um pouco
function spImportancia(fr, V, gancho) {
  const d = V.dados, s = spSemAcento(fr);
  const nome = spSemAcento(d.anunciante.replace(/\(.*?\)/g, '')).split(/\s+/).filter(Boolean).slice(-2).join(' ');
  const produto = (spSemAcento(d.oferta).match(/[a-z]{4,}/) || [''])[0];
  const rua = (spSemAcento(String(d.endereco || '').split(',')[0]).match(/[a-z]{4,}/g) || []).filter(x => !['avenida', 'rua', 'praca', 'travessa', 'rodovia', 'estrada'].includes(x)).pop() || '';
  let n = 0;
  if (spValores(fr).length) n += 4;
  if (nome && s.includes(nome)) n += 3;
  if (produto && s.includes(produto)) n += 3;
  if (rua && s.includes(rua)) n += 2;
  if ((fr.match(SP_FONE) || []).length) n += 2;
  if (gancho) n += 3;
  return n;
}
// hashtag que tenta ser o nome do anunciante tem que ser o nome certo ("#AçougueBomBom" ➜ "#AcougueBoiBom")
function spHashtags(t, V, trava) {
  const nome = V.dados.anunciante.replace(/\(.*?\)/g, '').trim(), certa = '#' + spSemAcento(nome).split(/[^a-z0-9]+/).filter(Boolean).map(p => p[0].toUpperCase() + p.slice(1)).join('');
  const inicio = (spSemAcento(nome).match(/[a-z0-9]{4,}/) || [''])[0];
  if (!inicio || certa.length < 4) return t;
  const alvo = certa.slice(1).toLowerCase(), vistas = new Set();
  return String(t || '').replace(/#[\p{L}\d_]+/gu, h => {
    const x = spSemAcento(h.slice(1));
    // "#Paroquia" (começo do nome) é hashtag de verdade; "#AçougueBomBom" é o nome escrito errado
    if (x.startsWith(inicio) && x !== alvo && !alvo.startsWith(x)) { trava.push(`legenda: hashtag "${h}" trocada por "${certa}"`); h = certa; }
    const k = spSemAcento(h);
    if (vistas.has(k)) return '';
    vistas.add(k);
    return h;
  }).replace(/[ \t]{2,}/g, ' ').trim();
}
// título da tela sem o preço (o preço vai no destaque, logo embaixo)
function spSemPreco(t) {
  let x = String(t || '').replace(/\s*(?:(?<![\p{L}\d])(?:por|a|apenas|s[óo]|de)\s+)?R\$\s?\d[\d.]*(?:,\d{1,2})?(?:\s+(?:o|a)\s+(?:quilo|kg|unidade|litro|pacote|caixa))?/giu, '')
    .replace(/\s+([!?.,])/g, '$1').replace(/\s{2,}/g, ' ').replace(/^[\s,;:–-]+|[\s,;:–-]+$/g, '').replace(/^(?:a|o|as|os|por|de)\s+/i, '').trim();
  x = x.charAt(0).toUpperCase() + x.slice(1);
  return x.replace(/[!.]*$/, '').length >= 8 ? x : String(t || '');
}
// status que a página de criação e a de ouvir leem (sem a chave)
function spStatus(sp) {
  const ARQ = String(sp.link).split('/webhook/')[0] + '/videos/arquivo/', prontas = sp.versoes.filter(v => v.mp3).length;
  return { id: sp.id, etapa: prontas ? 'pronto' : 'erro', versao: sp.versao, link: sp.link, segundos: sp.segundos, fundo: sp.fundo ? ARQ + sp.fundo : '',
    erro: prontas ? '' : 'A oficina não conseguiu gravar o áudio: ' + (sp.versoes[0].erro || 'tente de novo'),
    versoes: sp.versoes.map(v => ({ nome: v.nome, alvo: v.alvo, palavras: v.palavras, duracao: v.duracao, mp3: v.mp3 ? ARQ + v.mp3 : '', mp4: v.mp4 ? ARQ + v.mp4 : '', erro: v.erro || '', aviso: v.aviso || '' })),
    revisao: [...(sp.problemas || []), ...(sp.trava || [])].slice(0, 10) };
}
// sem nenhuma fala que preste: um texto simples com os dados do anunciante
function spPadrao(v, V) {
  const d = V.dados, partes = [`${d.anunciante}!`, d.oferta.replace(/[.!]*$/, '.'), d.preco ? d.preco.replace(/[.!]*$/, '.') : '', v.alvo >= 30 && d.validade ? `Válido ${d.validade.replace(/[.!]*$/, '.')}` : '',
    v.alvo >= 30 && d.endereco ? `Fica em ${d.endereco.replace(/[.!]*$/, '.')}` : '', d.telefone ? `WhatsApp ${d.telefone}.` : ''].filter(Boolean);
  return [{ quem: 'A', texto: partes.join(' ') }, { quem: 'V', texto: d.anunciante + (d.slogan ? '. ' + d.slogan.replace(/[.!]*$/, '.') : '.') }];
}

// Grava a versão refeita no spot RELIDO agora (outra versão pode ter sido refeita ao mesmo tempo) e sobe o número da versão do spot (a página espera por ele).
const C = $('🧩 Confere o refazer').first().json, o = $('🌐 Pergunta à oficina (refazer)').first().json || {};
const sp = JSON.parse($('📖 Lê o spot de novo').first().json.sp || 'null');
const r = (o.versoes || {})[C.arquivo] || {}, v = sp.versoes[C.k];
if (r.mp3) Object.assign(v, { falas: C.falas, palavras: C.palavras, arquivo: C.arquivo, refeita: C.n, mp3: r.mp3, mp4: r.mp4 || '', duracao: Number(r.duracao) || 0, ritmo: Number(r.ritmo) || 1,
  estado: 'pronto', erro: '', aviso: '' });
else v.aviso = 'A nova gravação falhou (' + String(r.erro || 'a oficina não terminou').slice(-120) + '): ficou a anterior.';
sp.versao = (Number(sp.versao) || 1) + 1;
if (C.trava.length) sp.trava = [...new Set([...(sp.trava || []), ...C.trava])].slice(-10);
return [{ json: { sp: JSON.stringify(sp), status: JSON.stringify(spStatus(sp)), ok: !!r.mp3 } }];

// a criação responde na hora; as IAs e a oficina continuam em segundo plano
const r = $input.first().json;
if (!r.ok) throw new Error('A criação recusou o teste: ' + (r.erros || [r.message || 'sem resposta']).join(' '));
return [{ json: { id: r.id, link: r.link, painel: r.painel, json: r.painel + '&json=1' } }];

// Confere cada passo do teste; se algo não bateu, o node fica vermelho dizendo o quê.
const l = $('👉 Guarda os links').first().json, st = $('🚦 Ficou pronto?').first().json;
const j = x => { if (typeof x.data === 'string') { try { return JSON.parse(x.data); } catch (e) { return { texto: x.data }; } } return x; };
const pag = String($('🌐 Abre a página').first().json.data || ''), dono = String($('🌐 Abre a página do dono').first().json.data || '');
const sp = j($('🌐 Spot em dados').first().json), mp3 = $('🌐 Baixa o MP3 de 15 s').first().json, mp4 = $('🌐 Baixa o vídeo de 30 s').first().json;
const errada = j($('🌐 Refaz com a chave errada').first().json), rf = j($('🌐 Refaz a versão de 15 s').first().json), sp2 = j($('🌐 Spot refeito em dados').first().json);
const falhas = [], ok = (c, m) => { if (!c) falhas.push(m); };
const vs = st.versoes || [], ALVO = { '15s': [14.5, 19], '30s': [29.5, 36], '60s': [59.5, 70] };
ok(st.etapa === 'pronto' && vs.length === 3 && vs.every(v => v.mp3 && v.mp4), 'O spot não ficou pronto com as 3 versões em MP3 e MP4: ' + JSON.stringify(st).slice(0, 400));
for (const v of vs) { const f = ALVO[v.nome] || [0, 0]; ok(v.duracao >= f[0] && v.duracao <= f[1], `A versão de ${v.nome} saiu com ${v.duracao} s (esperado entre ${f[0]} e ${f[1]})`); }
// o botão de editar é data-editar="15s" (o JavaScript da página também cita [data-editar], por isso a busca é pelo botão)
ok((pag.match(/<audio/g) || []).length === 3 && pag.includes('wa.me') && !pag.includes('data-editar="'), 'A página pública devia ter 3 players, o WhatsApp e NÃO ter o botão de editar');
ok((dono.match(/data-editar="/g) || []).length === 3 && dono.includes('link de dono'), 'A página do dono devia ter o botão de editar nas 3 versões');
ok(sp.id === l.id && !('chave' in sp), 'Os dados do spot não vieram (ou vieram com a chave): ' + JSON.stringify(sp).slice(0, 200));
const falas = (sp.versoes || []).flatMap(v => v.falas || []);
ok(!/Antonio/.test(JSON.stringify(sp.op || {})), 'Voz proibida (Antonio) no spot');
ok(falas.length >= 6 && falas.every(f => f.fala && !/\d/.test(f.fala)), 'Toda fala devia virar texto falado sem algarismos: ' + JSON.stringify(falas.filter(f => /\d/.test(f.fala || '')).slice(0, 2)));
const precos = falas.flatMap(f => [...String(f.texto).matchAll(/R\$\s?([\d.]+(?:,\d{1,2})?)/g)].map(m => m[1]));
ok(precos.every(p => p === '59,90'), 'Preço diferente do anunciante nas falas: ' + precos.join(', '));
ok(falas.some(f => /cinquenta e nove reais e noventa centavos/.test(f.fala)), 'O preço devia ser falado por extenso ("cinquenta e nove reais e noventa centavos") em alguma versão');
const fone = falas.filter(f => /9888/.test(f.texto));
ok(fone.every(f => /nove um, nove oito oito oito oito, sete sete sete sete/.test(f.fala)), 'Telefone falado errado: ' + JSON.stringify(fone.map(f => f.fala)).slice(0, 300));
ok(Number(mp3.statusCode) === 200 && /audio\/mpeg/.test(JSON.stringify(mp3.headers || {})), 'O MP3 de 15 s não abriu: ' + mp3.statusCode);
ok(Number(mp4.statusCode) === 200 && /video\/mp4/.test(JSON.stringify(mp4.headers || {})), 'O vídeo de 30 s não abriu: ' + mp4.statusCode);
ok(errada.ok === false && /Chave/i.test(errada.erro || ''), 'Refazer com a chave errada devia ser recusado: ' + JSON.stringify(errada));
ok(rf.ok === true && (rf.trava || []).some(t => /preço/.test(t)), 'O refazer devia aceitar e a trava tirar o R$ 99,90 inventado: ' + JSON.stringify(rf));
const v15 = (sp2.versoes || [])[0] || {};
ok(sp2.versao === 2 && v15.arquivo === '15sv2' && /spot-15sv2\.mp3$/.test(v15.mp3 || '') && /^Atenção, freguesia/.test(((v15.falas || [])[0] || {}).texto || '') && !JSON.stringify(v15.falas).includes('99,90'),
  'A versão de 15 s refeita não veio certa: ' + JSON.stringify({ versao: sp2.versao, arquivo: v15.arquivo, mp3: v15.mp3, fala1: ((v15.falas || [])[0] || {}).texto }).slice(0, 300));
if (falhas.length) throw new Error(falhas.join(' | '));
return [{ json: { '✅': `Spot pronto em ${st.segundos} s: 15 s (${vs[0].duracao} s), 30 s (${vs[1].duracao} s) e 1 min (${vs[2].duracao} s) em MP3 e vídeo; preço e telefone por extenso; página pública e de dono; refazer com trava de preço gravou a versão 2`,
  '🔊 página': l.link, '✏️ dono': l.painel, '🎧 15 s': vs[0].mp3, '🎬 30 s': vs[1].mp4, '🗣️ 1ª fala': ((sp.versoes || [])[0].falas || [])[0], '🔍 revisão': st.revisao } }];
